    <style>
        :root {
            --mega-ease: cubic-bezier(0.22, 0.61, 0.36, 1);
            --mega-height-speed: 0.45s;
            --mega-fade-speed: 0.32s;
            --mega-slide-speed: 0.5s;
            --mega-radius: 1.5rem;
            --navbar-radius-speed: 200ms;
            --navbar-radius-ease: ease;
            --navbar-chevron-speed: var(--navbar-radius-speed);
            --navbar-scroll-speed: 0.25s;
            /* scrolled bar speed */
            --navbar-scroll-ease: var(--mega-ease);
            --navbar-scroll-line: rgba(255, 255, 255, 0.16);
            --navbar-scroll-btm-pad: calc(0.75rem - 0.25rem * var(--navbar-scroll-hide-top-bar));
            --navbar-scroll-hide-top-bar: 0;
            /* 1 = hide top strip when scrolled, 0 = keep */
        }

        /* 1. Mega menu */
        .nav-mega-stack {
            position: absolute;
            top: 100%;
            left: 0;
            right: 0;
            height: 0;
            overflow: hidden;
            transition: height var(--mega-height-speed) var(--mega-ease), left var(--navbar-scroll-duration, 0s) var(--navbar-scroll-ease), right var(--navbar-scroll-duration, 0s) var(--navbar-scroll-ease), border-bottom-left-radius var(--navbar-scroll-duration, 0s) var(--navbar-scroll-ease), border-bottom-right-radius var(--navbar-scroll-duration, 0s) var(--navbar-scroll-ease);
            background-color: var(--color-scheme-1--dark-second, #0e121a);
            border-bottom-left-radius: var(--mega-radius);
            border-bottom-right-radius: var(--mega-radius);
        }

        .nav-mega-panel {
            position: absolute !important;
            top: 0 !important;
            left: 0 !important;
            right: 0 !important;
            width: 100%;
            height: auto !important;
            display: flex !important;
            background-color: transparent !important;
            opacity: 0;
            pointer-events: none;
            transform: translateX(var(--mega-shift-x, 0px));
            transition: opacity var(--mega-fade-speed) var(--mega-ease), transform var(--mega-slide-speed) var(--mega-ease);
        }

        .nav-mega-panel[data-mega-active] {
            opacity: 1;
            pointer-events: auto;
            transform: translateX(0px);
        }

        .navbar-v2 .nav-mega-panel.w--open {
            transition: opacity var(--mega-fade-speed) var(--mega-ease), transform var(--mega-slide-speed) var(--mega-ease);
        }

        /* 2. Navbar corners */
        .navbar-v2 {
            transition: border-bottom-left-radius var(--navbar-radius-speed) var(--navbar-radius-ease) var(--mega-height-speed), border-bottom-right-radius var(--navbar-radius-speed) var(--navbar-radius-ease) var(--mega-height-speed), translate var(--navbar-scroll-duration, 0s) var(--navbar-scroll-ease);
        }

        .navbar-v2.is-dropdown-open {
            border-bottom-left-radius: 0px !important;
            border-bottom-right-radius: 0px !important;
            transition-delay: 0s, 0s, 0s;
            transition-duration: 0s, 0s, var(--navbar-scroll-duration, 0s);
        }

        /* 3. Chevron */
        .nav_dropdown-chevron {
            transition: transform var(--navbar-chevron-speed) var(--navbar-radius-ease);
            transform-origin: 50% 50%;
        }

        .navbar-v2_dropdown.is-open .nav_dropdown-chevron {
            transform: rotate(180deg);
        }

        /* 4. Fluid column gap */
        @media (min-width: 992px) {
            .navbar-v2_dropdown-content-left {
                --gap-min: 24px;
                --gap-max: 48px;
                --gap-delta: 24;
                column-gap: clamp(var(--gap-min), calc(var(--gap-min) + (100vw - 992px) * var(--gap-delta) / 208), var(--gap-max)) !important;
            }
        }

        /* 5. data-hide-narrow */
        @media (min-width: 992px) and (max-width: 1130px) {
            [data-hide-narrow] {
                display: none !important;
            }
        }

        /* 6. Trigger colour */
        .navbar-v2_dropdown-toggle:hover,
        .navbar-v2_dropdown.is-open .navbar-v2_dropdown-toggle {
            color: var(--color-scheme-1--light-green, #c7ffbe) !important;
        }

        /* 7. Scrolled bar (desktop) */
        @media (min-width: 992px) {
            .navbar-v2 {
                --navbar-scroll-duration: var(--navbar-scroll-speed);
            }

            .navbar-v2.is-scrolled {
                translate: 0 calc(-1 * (var(--navbar-lift-base, 0px) + var(--navbar-lift-strip, 0px) * var(--navbar-scroll-hide-top-bar, 1)));
            }

            .navbar-v2.is-scrolled:has(.navbar-v2_top-bar :focus-visible) {
                translate: 0 calc(-1 * var(--navbar-lift-base, 0px));
            }

            .navbar-v2::before {
                content: '';
                display: block;
                position: absolute;
                z-index: -1;
                grid-area: auto;
                top: calc(-1 * var(--navbar-lift-base, 0px));
                bottom: -1px;
                left: calc(50% - 50vw);
                right: calc(50% - 50vw);
                border-bottom: 1px solid var(--navbar-scroll-line);
                background-color: inherit;
                opacity: 0;
                pointer-events: none;
                transition: opacity var(--navbar-scroll-duration, 0s) var(--navbar-scroll-ease);
            }

            .navbar-v2.is-scrolled::before {
                opacity: 1;
                pointer-events: auto;
            }

            .navbar-v2_btm-bar {
                transition: padding-bottom var(--navbar-scroll-duration, 0s) var(--navbar-scroll-ease);
            }

            .navbar-v2.is-scrolled .navbar-v2_btm-bar {
                padding-bottom: var(--navbar-scroll-btm-pad);
            }

            .navbar-v2.is-scrolled .nav-mega-stack {
                left: calc(50% - 50vw) !important;
                right: calc(50% - 50vw) !important;
                border-width: 0 !important;
                border-bottom-left-radius: 0;
                border-bottom-right-radius: 0;
                box-shadow: inset 0 -1px 0 var(--navbar-scroll-line);
            }

            .navbar-v2.is-scrolled .nav-mega-panel {
                width: var(--navbar-inner-width, 100%);
                min-width: 0;
                max-width: none;
                margin-left: auto;
                margin-right: auto;
            }
        }

        @media (prefers-reduced-motion: reduce) {
            :root {
                --navbar-scroll-speed: 0s;
            }

            .nav-mega-stack,
            .nav-mega-panel {
                transition: none !important;
            }
        }
    </style>
    <script>
        (function() {
            var NAVBAR = '.navbar-v2';
            var DROPDOWN = '.navbar-v2_dropdown';
            var TOGGLE = '.navbar-v2_dropdown-toggle';
            var LIST = '.navbar-v2_dropdown-list';

            var DESKTOP_MIN = 992;
            var CLOSE_DELAY = 250;
            var SHIFT = 20;
            var COLLAPSE_MS = 450;

            var BTM_BAR = '.navbar-v2_btm-bar';
            var TOP_BAR = '.navbar-v2_top-bar';
            var SCROLLED = 'is-scrolled';
            var SCROLL_RATIO = 0.3;

            // Mega menu
            function build(navbar) {
                var dropdowns = [].slice.call(navbar.querySelectorAll(DROPDOWN));
                if (!dropdowns.length)
                    return;

                var stack = document.createElement('div');
                stack.className = 'nav-mega-stack';
                navbar.appendChild(stack);

                var edge = {
                    left: '0 none',
                    right: '0 none',
                    bottom: '0 none',
                    bottomWidth: 0
                };
                var borderTimer = null;

                function syncStackEdges() {
                    var cs = getComputedStyle(navbar);
                    stack.style.left = -(parseFloat(cs.borderLeftWidth) || 0) + 'px';
                    stack.style.right = -(parseFloat(cs.borderRightWidth) || 0) + 'px';

                    edge.left = cs.borderLeftWidth + ' ' + cs.borderLeftStyle + ' ' + cs.borderLeftColor;
                    edge.right = cs.borderRightWidth + ' ' + cs.borderRightStyle + ' ' + cs.borderRightColor;
                    edge.bottom = cs.borderBottomWidth + ' ' + cs.borderBottomStyle + ' ' + cs.borderBottomColor;
                    edge.bottomWidth = parseFloat(cs.borderBottomWidth) || 0;

                    if (active)
                        showBorders();
                }

                function showBorders() {
                    stack.style.borderLeft = edge.left;
                    stack.style.borderRight = edge.right;
                    stack.style.borderBottom = edge.bottom;
                }

                function hideBorders() {
                    stack.style.borderLeft = stack.style.borderRight = stack.style.borderBottom = '0 none';
                }

                syncStackEdges();

                var panels = [];
                dropdowns.forEach(function(dropdown, index) {
                    var list = dropdown.querySelector(LIST);
                    if (!list)
                        return;
                    list.classList.add('nav-mega-panel', 'w--open');
                    stack.appendChild(list);
                    panels.push({
                        dropdown: dropdown,
                        toggle: dropdown.querySelector(TOGGLE),
                        panel: list,
                        index: index
                    });
                });
                if (!panels.length)
                    return;

                var active = null;
                var closeTimer = null;

                function placeInstantly(panel, offset) {
                    if (parseFloat(getComputedStyle(panel).opacity) > 0)
                        return;
                    panel.style.transition = 'none';
                    panel.style.setProperty('--mega-shift-x', offset + 'px');
                    void panel.offsetWidth;
                    panel.style.transition = '';
                }

                function open(entry) {
                    clearTimeout(closeTimer);
                    if (active === entry)
                        return;

                    var dir = active ? (entry.index > active.index ? 1 : -1) : 0;

                    if (active) {
                        active.panel.removeAttribute('data-mega-active');
                        active.panel.style.setProperty('--mega-shift-x', (-dir * SHIFT) + 'px');
                        active.dropdown.classList.remove('is-open');
                    }

                    placeInstantly(entry.panel, dir * SHIFT);
                    entry.panel.setAttribute('data-mega-active', '');
                    entry.dropdown.classList.add('is-open');

                    clearTimeout(borderTimer);
                    showBorders();

                    stack.style.height = (entry.panel.offsetHeight + edge.bottomWidth) + 'px';
                    navbar.classList.add('is-dropdown-open');
                    active = entry;
                }

                function close() {
                    if (!active)
                        return;
                    active.panel.removeAttribute('data-mega-active');
                    active.panel.style.setProperty('--mega-shift-x', '0px');
                    active.dropdown.classList.remove('is-open');
                    stack.style.height = '0px';
                    navbar.classList.remove('is-dropdown-open');
                    active = null;

                    clearTimeout(borderTimer);
                    borderTimer = setTimeout(hideBorders, COLLAPSE_MS);
                }

                function scheduleClose() {
                    clearTimeout(closeTimer);
                    closeTimer = setTimeout(close, CLOSE_DELAY);
                }

                panels.forEach(function(entry) {
                    entry.dropdown.addEventListener('mouseenter', function() {
                        open(entry);
                    });
                    if (entry.toggle) {
                        entry.toggle.addEventListener('focus', function() {
                            open(entry);
                        });
                    }
                });

                navbar.addEventListener('mouseover', function(e) {
                    if (!active)
                        return;
                    var target = e.target;
                    if (!target || !target.closest)
                        return;

                    var overTrigger = target.closest(DROPDOWN);
                    var overMenu = target.closest('.nav-mega-stack');

                    if (overTrigger || overMenu) {
                        clearTimeout(closeTimer);
                    } else {
                        scheduleClose();
                    }
                });

                navbar.addEventListener('mouseleave', scheduleClose);

                document.addEventListener('keydown', function(e) {
                    if (e.key === 'Escape')
                        close();
                });

                window.addEventListener('resize', function() {
                    syncStackEdges();
                    if (active)
                        stack.style.height = (active.panel.offsetHeight + edge.bottomWidth) + 'px';
                });
            }

            // Scrolled bar
            function watchScroll(navbar) {
                var btmBar = navbar.querySelector(BTM_BAR);
                var topBar = navbar.querySelector(TOP_BAR);
                var desktop = window.matchMedia('(min-width: ' + DESKTOP_MIN + 'px)');
                var state = null;
                var queued = false;

                if (topBar)
                    topBar.addEventListener('click', function(e) {
                        var link = e.detail && e.target.closest && e.target.closest('a, button');
                        if (link)
                            link.blur();
                    });

                function measure() {
                    var cs = getComputedStyle(navbar);
                    var box = navbar.getBoundingClientRect();
                    var bt = parseFloat(cs.borderTopWidth) || 0;
                    var base = (parseFloat(cs.top) || 0) + (parseFloat(cs.marginTop) || 0) + bt;
                    var strip = btmBar ? btmBar.getBoundingClientRect().top - box.top - bt : 0;
                    var inner = box.width - (parseFloat(cs.borderLeftWidth) || 0) - (parseFloat(cs.borderRightWidth) || 0);

                    navbar.style.setProperty('--navbar-lift-base', base + 'px');
                    navbar.style.setProperty('--navbar-lift-strip', Math.max(0, strip) + 'px');
                    navbar.style.setProperty('--navbar-inner-width', inner + 'px');
                }

                function update() {
                    queued = false;
                    var y = window.pageYOffset || document.documentElement.scrollTop || 0;
                    var next = desktop.matches && y > window.innerHeight * SCROLL_RATIO;
                    if (next === state)
                        return;
                    state = next;
                    if (next)
                        measure();
                    navbar.classList.toggle(SCROLLED, next);
                }

                function queue() {
                    if (queued)
                        return;
                    queued = true;
                    requestAnimationFrame(update);
                }

                window.addEventListener('scroll', queue, {
                    passive: true
                });

                window.addEventListener('resize', function() {
                    if (desktop.matches)
                        measure();
                    queue();
                });

                if (document.fonts && document.fonts.ready) {
                    document.fonts.ready.then(function() {
                        if (desktop.matches)
                            measure();
                    });
                }

                if (desktop.matches)
                    measure();
                update();
            }

            function init() {
                if (window.innerWidth < DESKTOP_MIN)
                    return;

                var navbars = document.querySelectorAll(NAVBAR);
                var i;

                for (i = 0; i < navbars.length; i++)
                    watchScroll(navbars[i]);
                for (i = 0; i < navbars.length; i++)
                    build(navbars[i]);
            }

            if (document.readyState === 'loading') {
                document.addEventListener('DOMContentLoaded', init);
            } else {
                init();
            }
        })();
